-- c003-v011: जल्दी–करो और–आओ सब– जातियो चारों–ओर–से और–इकट्ठे–हो वहाँ उतार यहोवा वीरों–अपने–को।
-- c003-v012: जागें और–चढ़–आएँ जातियाँ को– तराई यहोशापात–की क्योंकि वहाँ बैठूँगा न्याय–करने को– सब– जातियों चारों–ओर–से।
-- c003-v013: चलाओ हँसिया क्योंकि पक–गई फसल आओ उतरो क्योंकि– भर–गया हौद उमड़–रहे–हैं कुंड क्योंकि बड़ी बुराई–उनकी।
-- c003-v014: भीड़ भीड़ में–तराई निर्णय–की क्योंकि निकट दिन यहोवा–का में–तराई निर्णय–की।
-- c003-v015: सूर्य और–चंद्रमा काले–पड़–गए और–तारे समेट–लेते–हैं चमक–अपनी।
-- c003-v016: और–यहोवा से–सिय्योन गरजेगा और–से–यरूशलेम देगा आवाज़–अपनी और–काँपेंगे आकाश और–पृथ्वी और–यहोवा शरण के–लिए–प्रजा–अपनी और–गढ़ के–लिए–पुत्रों इस्राएल–के।
-- c003-v017: और–जानोगे कि मैं यहोवा एलोहीम–तुम्हारा निवास–करने–वाला में–सिय्योन पर्वत– पवित्र–मेरे और–होगी यरूशलेम पवित्र और–परदेशी नहीं– गुज़रेंगे– उसमें फिर। 
-- c003-v018: और–होगा में–दिन उस टपकेंगे पहाड़ मीठी–दाखमधु और–पहाड़ियाँ बहेंगी दूध और–सब– नाले यहूदा–के बहेंगे पानी और–सोता से–भवन यहोवा–के निकलेगा और–सींचेगा को– नाला शित्तीम–का।
